### Jenkins

```groovy
pipeline {
    agent any
    stages {
        stage('Build') {
            steps {
                script {
                    // Docker daemon runs as service on most Jenkins agents
                    sh 'python _helpers/scripts/build_docker.py --docker-env=dev --push'
                }
            }
        }
    }
}
```
